  ('score', '{"sem_site":30,"instagram_movimento":20,"dono_acessivel":15,"gmb_fraco":15,"nicho_conhecido":10,"timing":10,"fonte":"Horus-Comercial/30-checklist-qualificacao.md"}'),
  ('nichos_conhecidos', '["floricultura","flores","café","cafe","psicologia","psicólogo","estética","estetica","odontologia","dentista","oficina","automotiv","fitness","academia","pilates","estúdio","massoterapia","doceria","confeitaria","arquitetura","interiores","clínica","clinica"]'),
